                cx = (Evidence.PaGet(pa, i, Evidence.PfX0()) + Evidence.PaGet(pa, i, Evidence.PfX1())) / 2;
                cy = (Evidence.PaGet(pa, i, Evidence.PfY0()) + Evidence.PaGet(pa, i, Evidence.PfY1())) / 2;
                if ((cx >= (rx0 - 100)) && ((cx <= (rx1 + 100)) && ((cy >= (ry0 - 100)) && (cy <= (ry1 + 100))))) {
                    FcOnePath(pa, i, rx0, ry0, rx1, ry1, ws);
                }
            }
            i += 1;
        }
        if (emon.Port.CellsAt(ws, FtNp) == 0) {
            i = 0;
            while (i < ng) {
                if (Glayer.GrlGet(grl, i, 0) == page) {
                    cx = (Glayer.GrlGet(grl, i, 1) + Glayer.GrlGet(grl, i, 3)) / 2;
                    cy = (Glayer.GrlGet(grl, i, 2) + Glayer.GrlGet(grl, i, 4)) / 2;
                    if ((cx >= rx0) && ((cx <= rx1) && ((cy >= ry0) && (cy <= ry1)))) {
                        if (Glayer.GrlGet(grl, i, 10) == Glayer.GoH()) {
                            span = Glayer.GrlGet(grl, i, 3) - Glayer.GrlGet(grl, i, 1);
                            if ((span >= 3000) && ((span * 100) >= (rw * 45))) {
                                FcInc(ws, FtNhl);
                                if (span > emon.Port.CellsAt(ws, FtHlen)) {
                                    emon.Port.CellsSet(ws, FtHlen, span);
                                    emon.Port.CellsSet(ws, FtHx0, Glayer.GrlGet(grl, i, 1));
                                    emon.Port.CellsSet(ws, FtHx1, Glayer.GrlGet(grl, i, 3));
                                    emon.Port.CellsSet(ws, FtHy, cy);
                                }
                            }
                        }
                        if (Glayer.GrlGet(grl, i, 10) == Glayer.GoV()) {
                            span = Glayer.GrlGet(grl, i, 4) - Glayer.GrlGet(grl, i, 2);
                            if ((span >= 2500) && ((span * 100) >= (rh * 40))) {
                                FcInc(ws, FtNvl);
                                if (span > emon.Port.CellsAt(ws, FtVlen)) {
                                    emon.Port.CellsSet(ws, FtVlen, span);
                                    emon.Port.CellsSet(ws, FtVx, cx);
                                    emon.Port.CellsSet(ws, FtVy0, Glayer.GrlGet(grl, i, 2));
                                    emon.Port.CellsSet(ws, FtVy1, Glayer.GrlGet(grl, i, 4));
