    }
    internal static int FcPack(int kind, int conf) {
        return (kind * 1024) + conf;
    }
    internal static int FcPow2(int k) {
        int v = 1;
        int i = 0;
        while (i < k) {
            v *= 2;
            i += 1;
        }
        return v;
    }
    internal static int FcHamming16(int a, int b) {
        // The number of the 16 low bits in which a and b differ.
        int k = 0;
        int d = 0;
        while (k < 16) {
            if (((a / FcPow2(k)) % 2) != ((b / FcPow2(k)) % 2)) {
                d += 1;
            }
            k += 1;
        }
        return d;
    }
    internal static int FcSignVector(emon.Port.Cells pa, emon.Port.Cells fcand, int row) {
        // P8.4: the signature of a small vector region (`CR_SIG`): the paths of its page whose centres lie in its visible box, and the 4 x 4 grid
        // of the box that those centres fall in (a 16 bit mask). It does not depend on the scale. Answers the paths read.
        int b = row * CrStride;
        int page = emon.Port.CellsAt(fcand, b + CrPage);
        int x0 = emon.Port.CellsAt(fcand, b + CrVx);
        int y0 = emon.Port.CellsAt(fcand, b + (CrVx + 1));
        int w = emon.Port.CellsAt(fcand, b + (CrVx + 2)) - x0;
        int h = emon.Port.CellsAt(fcand, b + (CrVx + 3)) - y0;
        int n = emon.Port.CellsLen(pa) / 24;
        int pend = Pagebounds.PbAfter(pa, 24, page);
        int i = Pagebounds.PbFirst(pa, 24, page);
        int np = 0;
        int mask = 0;
        int cx = 0;
        int cy = 0;
        int gx = 0;
        int gy = 0;
        int bit = 0;
        if ((w <= 0) || (h <= 0)) {
            return 0;
        }
        while (i < pend) {
            if ((Evidence.PaGet(pa, i, Evidence.PfPage()) == page) && ((Evidence.PaGet(pa, i, Evidence.PfVis()) == 0) && ((Evidence.PaGet(pa, i, Evidence.PfFlags()) & Evidence.PgClip()) == 0))) {
                cx = (Evidence.PaGet(pa, i, Evidence.PfX0()) + Evidence.PaGet(pa, i, Evidence.PfX1())) / 2;
                cy = (Evidence.PaGet(pa, i, Evidence.PfY0()) + Evidence.PaGet(pa, i, Evidence.PfY1())) / 2;
                if ((cx >= x0) && ((cx <= (x0 + w)) && ((cy >= y0) && (cy <= (y0 + h))))) {
                    np += 1;
                    gx = FcMin(3, ((cx - x0) * 4) / w);
                    gy = FcMin(3, ((cy - y0) * 4) / h);
                    bit = FcPow2((gy * 4) + gx);
                    if (((mask / bit) % 2) == 0) {
                        mask += bit;
                    }
                }
            }
            i += 1;
        }
        if (np >= 2) {
            emon.Port.CellsSet(fcand, b + CrSig, 2);
            emon.Port.CellsSet(fcand, b + (CrSig + 1), np);
            emon.Port.CellsSet(fcand, b + (CrSig + 2), mask);
        }
        return n;
    }
    public static int FcSignRows(emon.Port.Cells fi, emon.Port.Cells pa, emon.Port.Cells fcand) {
        // P8.4: the recurrence signature (`CR_SIG`) of every candidate row that could be a logo: an image placement (its object and its stream's
        // digest, `fc-digest`) and a small vector region (`fc-sign-vector`). Rows of regions beyond the document's budget (`FC_RWORK`) have none.
        int n = emon.Port.CellsLen(fcand) / CrStride;
        int r = 0;
        int b = 0;
        int fb = 0;
        int work = 0;
        while (r < n) {
            b = r * CrStride;
            if (emon.Port.CellsAt(fcand, b + CrKori) == -1) {
                fb = emon.Port.CellsAt(fcand, b + CrRow) * FiStride;
                if ((fb >= 0) && (((fb + FiStride) <= emon.Port.CellsLen(fi)) && (emon.Port.CellsAt(fi, fb) == 1))) {
                    emon.Port.CellsSet(fcand, b + CrSig, 1);
                    emon.Port.CellsSet(fcand, b + (CrSig + 1), emon.Port.CellsAt(fi, fb + 10));
                    emon.Port.CellsSet(fcand, b + (CrSig + 2), emon.Port.CellsAt(fi, fb + 11));
                    emon.Port.CellsSet(fcand, b + (CrSig + 3), emon.Port.CellsAt(fi, fb + 5));
                    emon.Port.CellsSet(fcand, b + (CrSig + 4), emon.Port.CellsAt(fi, fb + 6));
                }
            } else if ((emon.Port.CellsAt(fcand, b + CrKori) == -2) && (work < FcRwork)) {
                if (((emon.Port.CellsAt(fcand, b + (CrVx + 2)) - emon.Port.CellsAt(fcand, b + CrVx)) <= FcSmall) && ((emon.Port.CellsAt(fcand, b + (CrVx + 3)) - emon.Port.CellsAt(fcand, b + (CrVx + 1))) <= FcSmall)) {
                    work += FcSignVector(pa, fcand, r);
                }
            }
            r += 1;
        }
        return 0;
    }
    internal static int FcSameDrawing(emon.Port.Cells cand, emon.Port.Cells pages, int a, int b) {
        // 1 when the candidate rows a and b (on two pages) are one logo: the same image object, or an image of the same size whose stream has
        // the same digest; or vector art with as many paths, the same 4 x 4 occupancy (within one cell), a size within `FC_RSCALE_LO`..`FC_RSCALE_HI`
        // per mille of the other's, and its centre at the same place of the page (within `FC_RPOS` per mille and an eighth of its size).
        int ba = a * CrStride;
        int bb = b * CrStride;
        int ka = emon.Port.CellsAt(cand, ba + CrSig);
        if ((ka == 0) || (ka != emon.Port.CellsAt(cand, bb + CrSig))) {
            return 0;
        }
        if (ka == 1) {
            if ((emon.Port.CellsAt(cand, ba + CrObj) > 0) && (emon.Port.CellsAt(cand, ba + CrObj) == emon.Port.CellsAt(cand, bb + CrObj))) {
                return 1;
            }
            if ((emon.Port.CellsAt(cand, ba + (CrSig + 1)) > 0) && ((emon.Port.CellsAt(cand, ba + (CrSig + 1)) == emon.Port.CellsAt(cand, bb + (CrSig + 1))) && ((emon.Port.CellsAt(cand, ba + (CrSig + 2)) == emon.Port.CellsAt(cand, bb + (CrSig + 2))) && ((emon.Port.CellsAt(cand, ba + (CrSig + 3)) == emon.Port.CellsAt(cand, bb + (CrSig + 3))) && (emon.Port.CellsAt(cand, ba + (CrSig + 4)) == emon.Port.CellsAt(cand, bb + (CrSig + 4))))))) {
                return 1;
            }
            return 0;
        }
        int pwa = Model.PageW(pages, emon.Port.CellsAt(cand, ba + CrPage) - 1);
        int pha = Model.PageH(pages, emon.Port.CellsAt(cand, ba + CrPage) - 1);
        int pwb = Model.PageW(pages, emon.Port.CellsAt(cand, bb + CrPage) - 1);
        int phb = Model.PageH(pages, emon.Port.CellsAt(cand, bb + CrPage) - 1);
        int wa = emon.Port.CellsAt(cand, ba + (CrVx + 2)) - emon.Port.CellsAt(cand, ba + CrVx);
        int ha = emon.Port.CellsAt(cand, ba + (CrVx + 3)) - emon.Port.CellsAt(cand, ba + (CrVx + 1));
        int wb = emon.Port.CellsAt(cand, bb + (CrVx + 2)) - emon.Port.CellsAt(cand, bb + CrVx);
        int hb = emon.Port.CellsAt(cand, bb + (CrVx + 3)) - emon.Port.CellsAt(cand, bb + (CrVx + 1));
        if ((pwa <= 0) || ((pha <= 0) || ((pwb <= 0) || ((phb <= 0) || ((wb <= 0) || (hb <= 0)))))) {
            return 0;
        }
        if (emon.Port.CellsAt(cand, ba + (CrSig + 1)) != emon.Port.CellsAt(cand, bb + (CrSig + 1))) {
            return 0;
        }
        if (FcHamming16(emon.Port.CellsAt(cand, ba + (CrSig + 2)), emon.Port.CellsAt(cand, bb + (CrSig + 2))) > 1) {
            return 0;
        }
        if ((((wa * 1000) / wb) < FcRscaleLo) || (((wa * 1000) / wb) > FcRscaleHi)) {
            return 0;
        }
        if ((((ha * 1000) / hb) < FcRscaleLo) || (((ha * 1000) / hb) > FcRscaleHi)) {
            return 0;
        }
        int dx = FcAbs((((emon.Port.CellsAt(cand, ba + CrVx) + emon.Port.CellsAt(cand, ba + (CrVx + 2))) * 500) / pwa) - (((emon.Port.CellsAt(cand, bb + CrVx) + emon.Port.CellsAt(cand, bb + (CrVx + 2))) * 500) / pwb));
        int dy = FcAbs((((emon.Port.CellsAt(cand, ba + (CrVx + 1)) + emon.Port.CellsAt(cand, ba + (CrVx + 3))) * 500) / pha) - (((emon.Port.CellsAt(cand, bb + (CrVx + 1)) + emon.Port.CellsAt(cand, bb + (CrVx + 3))) * 500) / phb));
        if (dx > (FcRpos + (((wb * 1000) / pwb) / 8))) {
            return 0;
        }
        if (dy > (FcRpos + (((hb * 1000) / phb) / 8))) {
            return 0;
        }
        return 1;
    }
    public static int FcRecur(emon.Port.Cells cand, emon.Port.Cells pages, int row) {
        // P8.4 (logos and their recurrence across pages): how much the same drawing on other pages should raise the confidence of a logo (per
        // mille) for the region `row` of `cand`, whose signatures `fc-sign-rows` made: 0 for none, 100 when it is on one other page, 160 on two,
        // 220 on three or more. Pages, not placements: a drawing used twice on one page is no recurrence. A raster is the same by its object or
        // its stream's digest wherever it stands; vector art by `fc-same-drawing`'s place and shape, whatever the scale within the tolerance.
        int n = emon.Port.CellsLen(cand) / CrStride;
        int mine = emon.Port.CellsAt(cand, (row * CrStride) + CrPage);
        int r = 0;
        int pg = 0;
        int p1 = 0;
        int p2 = 0;
        int p3 = 0;
        int seen = 0;
        if (emon.Port.CellsAt(cand, (row * CrStride) + CrSig) == 0) {
            return 0;
        }
        while ((r < n) && (seen < 3)) {
            pg = emon.Port.CellsAt(cand, (r * CrStride) + CrPage);
            if ((pg != mine) && ((pg != p1) && ((pg != p2) && (pg != p3)))) {
                if (FcSameDrawing(cand, pages, row, r) == 1) {
                    if (seen == 0) {
                        p1 = pg;
                    }
                    if (seen == 1) {
                        p2 = pg;
                    }
                    if (seen == 2) {
                        p3 = pg;
                    }
                    seen += 1;
                }
            }
            r += 1;
        }
        if (seen == 0) {
            return 0;
        }
        if (seen == 1) {
            return 100;
        }
        if (seen == 2) {
            return 160;
        }
        return 220;
    }
    internal static int FcInBand(int y0, int y1, int pageh) {
        // 1 when the region lies in the header band (the top fifth of the page) or the footer band.
        if ((pageh > 0) && (((y1 / 10) * 1000) <= ((pageh / 10) * FcBand))) {
            return 1;
        }
        if ((pageh > 0) && (((y0 / 10) * 1000) >= ((pageh / 10) * (1000 - FcBand)))) {
            return 1;
        }
        return 0;
    }
    public static int FcVectorKind(emon.Port.Cells ws, int rx0, int ry0, int rx1, int ry1, int pageh, int recur) {
        // The kind and confidence of a region from its measured features: `fc-pack`ed. 0 kind is none (see `fc-judge`).
        int rw = rx1 - rx0;
        int rh = ry1 - ry0;
        int np = emon.Port.CellsAt(ws, FtNp);
        int axes = emon.Port.CellsAt(ws, FtAxes);
        int bars = emon.Port.CellsAt(ws, FtBars);
        int ticks = emon.Port.CellsAt(ws, FtTicks);
        int series = emon.Port.CellsAt(ws, FtSeries);
        int slant = emon.Port.CellsAt(ws, FtSlant);
        int num = emon.Port.CellsAt(ws, FtNum);
        int conf = 0;
        int banner = 0;
        // P11.x2 (D545): rules that meet and a few numbers are a chart only while what is in the region is a chart's text; with a
        // line of five words or more in it, and no mark of data (ticks, bars, a series), they are a banner or a framed box (a form's
        // title band, a signature box), which is no figure.
        if ((emon.Port.CellsAt(ws, FtProse) >= 1) && ((bars < 2) && ((series < 1) && ((slant < 2) && (ticks < 2))))) {
            banner = 1;
        }
        if ((banner == 0) && ((axes == 1) && ((bars >= 2) || ((series >= 1) || ((slant >= 2) || ((ticks >= 2) || (num >= 2))))))) {
            conf = 640;
            if (ticks >= 3) {
                conf += 40;
            }
            if ((bars >= 2) || ((series >= 1) || (slant >= 2))) {
                conf += 40;
            }
            if (num >= 2) {
                conf += 40;
            }
            return FcPack(Model.FgChart(), conf);
        }
        if ((emon.Port.CellsAt(ws, FtThin) >= 12) && ((emon.Port.CellsAt(ws, FtAligned) * 10) >= (emon.Port.CellsAt(ws, FtThin) * 8))) {
            return FcPack(Model.FgBarcode(), 700);
        }
        if ((emon.Port.CellsAt(ws, FtTiny) >= 40) && (((rw * 10) <= (rh * 14)) && ((rh * 10) <= (rw * 14)))) {
            return FcPack(Model.FgQr(), 700);
        }
        if ((emon.Port.CellsAt(ws, FtNcol) >= 3) && ((emon.Port.CellsAt(ws, FtWedge) >= 3) && (((rw * 10) <= (rh * 17)) && ((rh * 10) <= (rw * 17))))) {
            conf = 560;
            if (emon.Port.CellsAt(ws, FtSwatch) >= 2) {
                conf = 620;
            }
            return FcPack(Model.FgChart(), conf);
        }
        if ((bars >= 3) && (emon.Port.CellsAt(ws, FtBarvar) == 1)) {
            return FcPack(Model.FgChart(), 560);
        }
        if ((banner == 0) && ((axes == 1) && ((emon.Port.CellsAt(ws, FtNhl) + emon.Port.CellsAt(ws, FtNvl)) >= 2))) {
            return FcPack(Model.FgChart(), 520);
        }
        if ((axes == 0) && ((emon.Port.CellsAt(ws, FtBoxw) >= 2) && (emon.Port.CellsAt(ws, FtConn) >= 1))) {
            conf = 600;
            if (emon.Port.CellsAt(ws, FtBoxw) >= 3) {
                conf += 50;
            }
            if (emon.Port.CellsAt(ws, FtArrow) >= 1) {
                conf += 50;
            }
            return FcPack(Model.FgDiagram(), conf);
        }
        if ((FcMax(rw, rh) <= FcSmall) && ((np <= 24) && ((emon.Port.CellsAt(ws, FtProse) == 0) && ((FcInBand(ry0, ry1, pageh) == 1) || (recur > 0))))) {
            conf = 480 + recur;
            if (emon.Port.CellsAt(ws, FtColor) >= 1) {
                conf += 60;
            }
            if ((emon.Port.CellsAt(ws, FtWords) >= 1) && (emon.Port.CellsAt(ws, FtWords) <= 3)) {
                conf += 40;
            }
            return FcPack(Model.FgLogo(), FcMin(conf, 1000));
        }
        if ((emon.Port.CellsAt(ws, FtShade) >= 1) && ((np <= 3) && (emon.Port.CellsAt(ws, FtInside) == 0))) {
            return FcPack(Model.FgPhoto(), 520);
        }
        if ((emon.Port.CellsAt(ws, FtFrame) >= 1) && ((rw >= 15000) && ((rh >= 8000) && ((emon.Port.CellsAt(ws, FtInside) >= 1) && (emon.Port.CellsAt(ws, FtInside) <= 8))))) {
            return FcPack(Model.FgScreenshot(), 520);
        }
        if ((np >= 60) && ((((emon.Port.CellsAt(ws, FtCurve) + emon.Port.CellsAt(ws, FtOther)) * 2) >= np) && ((emon.Port.CellsAt(ws, FtWords) >= 6) && ((rw >= 20000) && (rh >= 15000))))) {
            return FcPack(Model.FgMap(), 540);
        }
        if ((np >= 8) && (((emon.Port.CellsAt(ws, FtCurve) + emon.Port.CellsAt(ws, FtOther)) * 2) >= np)) {
            return FcPack(Model.FgIllustration(), 520);
        }
        return FcPack(Model.FgUnknown(), 300);
    }
    public static int FcImageKind(emon.Port.Cells fi, int imx, int rw, int rh, int ry0, int ry1, int pageh, int recur) {
        // The kind and confidence of an image placement (row `imx` of `im`, its dictionary's row in `fi`), `fc-pack`ed: a raster that
        // needed many bits a pixel is a photograph, a flat two-colour one a code, a small flat one at the head or foot of the page a logo.
        int b = imx * FiStride;
        int conf = 0;
        if ((imx < 0) || (emon.Port.CellsLen(fi) < (b + FiStride))) {
            return FcPack(Model.FgUnknown(), 300);
        }
        if (emon.Port.CellsAt(fi, b) == 0) {
            return FcPack(Model.FgUnknown(), 300);
        }
        if ((emon.Port.CellsAt(fi, b + 4) == 1) || ((emon.Port.CellsAt(fi, b + 2) == 0) || ((emon.Port.CellsAt(fi, b + 1) == 9) || (emon.Port.CellsAt(fi, b + 1) == 10)))) {
            if (((rw * 10) >= (rh * 22)) && (rh <= 9000)) {
                return FcPack(Model.FgBarcode(), 540);
            }
            if (((rw * 100) >= (rh * 80)) && (((rw * 100) <= (rh * 125)) && (FcMax(rw, rh) <= 20000))) {
                return FcPack(Model.FgQr(), 540);
            }
            return FcPack(Model.FgIllustration(), 520);
        }
        if (emon.Port.CellsAt(fi, b + 7) >= FcPhotoBpp) {
            conf = 560 + FcMin(240, (emon.Port.CellsAt(fi, b + 7) - FcPhotoBpp) / 2);
            return FcPack(Model.FgPhoto(), conf);
        }
        if ((FcMax(rw, rh) <= FcSmall) && ((FcInBand(ry0, ry1, pageh) == 1) || ((emon.Port.CellsAt(fi, b + 9) >= 1) || (recur > 0)))) {
            return FcPack(Model.FgLogo(), FcMin(1000, 580 + recur));
        }
        if ((rw >= 20000) && (rh >= 12000)) {
            return FcPack(Model.FgScreenshot(), 450);
        }
        return FcPack(Model.FgUnknown(), 300);
    }
    public static int FcReject(emon.Port.Cells ws) {
        // 1 when the measured region is no figure: covered with prose, a seal (rings one in another) or a lattice of rules with no axes.
        if (emon.Port.CellsAt(ws, FtProse) >= 2) {
            return 1;
        }
        if (emon.Port.CellsAt(ws, FtRing) >= 1) {
            return 1;
        }
        if ((emon.Port.CellsAt(ws, FtAxes) == 0) && ((emon.Port.CellsAt(ws, FtNhl) >= 3) && (emon.Port.CellsAt(ws, FtNvl) >= 3))) {
            return 1;
        }
        return 0;
    }
    internal static int FcTaken(emon.Port.Cells fcand, int row, int page, int cx0, int cx1, int cy0) {
        // 1 when another candidate region of the page lies just above the caption (box cx0..cx1 x, top cy0): the caption is its, not the
        // region's below it (a figure's caption is under it).
        int n = emon.Port.CellsLen(fcand) / CrStride;
        int r = 0;
        int b = 0;
        while (r < n) {
            b = r * CrStride;
            if ((r != row) && ((emon.Port.CellsAt(fcand, b + CrPage) == page) && ((FcMin(cx1, emon.Port.CellsAt(fcand, b + (CrVx + 2))) > FcMax(cx0, emon.Port.CellsAt(fcand, b + CrVx))) && (((cy0 - emon.Port.CellsAt(fcand, b + (CrVx + 3))) >= -200) && ((cy0 - emon.Port.CellsAt(fcand, b + (CrVx + 3))) <= FcCapgap))))) {
                return 1;
            }
            r += 1;
        }
        return 0;
    }
    internal static int FcCaptioned(emon.Port.Cells nodes, emon.Port.Cells regions, emon.Port.Cells fcand, int row, int page, int x0, int y0, int x1, int y1) {
        // 1 when a figure's caption (a `caption` the notes stage made of a `Figure` label) lies within `FC_CAPGAP` below the box, or above it when
        // no other region lies above that caption (`fc-taken`).
        int nn = Model.NodeCount(nodes);
        int n = 0;
        int r = 0;
        while (n < nn) {
            if ((Model.NodeKind(nodes, n) == Model.NkCaption()) && (Model.NodeAux(nodes, n) == 1)) {
                r = Model.NodeRegionHead(nodes, n);
                if ((r >= 0) && ((Model.RegionPage(regions, r) == page) && (FcMin(x1, Model.RegionX1(regions, r)) > FcMax(x0, Model.RegionX0(regions, r))))) {
                    if (((Model.RegionY0(regions, r) - y1) >= -200) && ((Model.RegionY0(regions, r) - y1) <= FcCapgap)) {
                        return 1;
                    }
                    if (((y0 - Model.RegionY1(regions, r)) >= -200) && ((y0 - Model.RegionY1(regions, r)) <= FcCapgap)) {
                        if (FcTaken(fcand, row, page, Model.RegionX0(regions, r), Model.RegionX1(regions, r), Model.RegionY0(regions, r)) == 0) {
                            return 1;
                        }
                    }
                }
            }
            n += 1;
        }
        return 0;
    }
    internal static int FcLink(emon.Port.Cells cand, int page, int x0, int y0, int x1, int y1) {
        // The asset stage's candidate row (an image's) with this placement box on this page, or -1.
        int n = emon.Port.CellsLen(cand) / CrStride;
        int r = 0;
        int b = 0;
        while (r < n) {
            b = r * CrStride;
            if ((emon.Port.CellsAt(cand, b + CrPage) == page) && ((emon.Port.CellsAt(cand, b + CrKori) >= -1) && ((emon.Port.CellsAt(cand, b + CrBx) == x0) && ((emon.Port.CellsAt(cand, b + (CrBx + 1)) == y0) && ((emon.Port.CellsAt(cand, b + (CrBx + 2)) == x1) && (emon.Port.CellsAt(cand, b + (CrBx + 3)) == y1)))))) {
                return r;
            }
            r += 1;
        }
        return -1;
    }
    internal static int FcSignatureOver(emon.Port.Cells sl, int page, int x0, int y0, int x1, int y1) {
        // 1 when a signature or initials READ FROM PIXELS (an `sl` row of kind 3 or 4 with flag 128: `emon.sigpx`'s) lies in the region on its page: its box is at least half of the region
        // and the region is at most four times its box (the picture of a signature is the signature's placeholder and no figure: SPEC 10.7, P8.3, D430; a signature inside a photograph is not
        // this). A region that no figure was made of keeps its words in the body: they were the figure's `labels` otherwise.
        int n = emon.Port.CellsLen(sl) / 16;
        int j = 0;
        int q = 0;
        int ow = 0;
        int oh = 0;
        int area = 0;
        int sa = 0;
        int ra = 0;
        while (j < n) {
            q = j * 16;
            if ((emon.Port.CellsAt(sl, q) == page) && ((emon.Port.CellsAt(sl, q + 5) >= 3) && ((emon.Port.CellsAt(sl, q + 5) <= 4) && ((emon.Port.CellsAt(sl, q + 12) & 128) != 0)))) {
                ow = FcMin(x1, emon.Port.CellsAt(sl, q + 3)) - FcMax(x0, emon.Port.CellsAt(sl, q + 1));
                oh = FcMin(y1, emon.Port.CellsAt(sl, q + 4)) - FcMax(y0, emon.Port.CellsAt(sl, q + 2));
                if ((ow > 0) && (oh > 0)) {
                    area = (ow / 100) * (oh / 100);
                    sa = ((emon.Port.CellsAt(sl, q + 3) - emon.Port.CellsAt(sl, q + 1)) / 100) * ((emon.Port.CellsAt(sl, q + 4) - emon.Port.CellsAt(sl, q + 2)) / 100);
                    ra = ((x1 - x0) / 100) * ((y1 - y0) / 100);
                    if (((area * 2) >= ra) && (ra <= (sa * 4))) {
                        return 1;
                    }
                }
            }
            j += 1;
        }
        return 0;
    }
    public static int FcClaimed(emon.Port.Cells fl, int page, int x0, int y0, int x1, int y1) {
        // 1 when a table has claimed the text of the region (D557): of the lines on the page whose centre is in it, at least one and at least
        // half are a table's (cell 15 of a line a table holds is `FC_HELD` and up, `emon.table`'s TB_HELD). A shaded header cell with its words and
        // a rule under it, or a table's fills and rules, look like a diagram's boxes and a connector; the words are the table's, and so is the drawing.
        int n = Pagebounds.PbAfter(fl, 16, page);
        int l = Pagebounds.PbFirst(fl, 16, page);
        int total = 0;
        int held = 0;
        int cx = 0;
        int cy = 0;
        while (l < n) {
            if (Evidence.LnGet(fl, l, Evidence.LhPage()) == page) {
                cx = (Evidence.LnGet(fl, l, Evidence.LhX0()) + Evidence.LnGet(fl, l, Evidence.LhX1())) / 2;
                cy = (Evidence.LnGet(fl, l, Evidence.LhY0()) + Evidence.LnGet(fl, l, Evidence.LhY1())) / 2;
                if ((cx >= x0) && ((cx <= x1) && ((cy >= y0) && (cy <= y1)))) {
                    total += 1;
                    if (Evidence.LnGet(fl, l, 15) >= FcHeld) {
                        held += 1;
                    }
                }
            }
            l += 1;
        }
        if ((held > 0) && ((held * 2) >= total)) {
            return 1;
        }
        return 0;
    }
    public static int FcStage(emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells text, emon.Port.Cells pages, emon.Port.Cells fnodes, emon.Port.Cells fattrs, emon.Port.Cells fregions, emon.Port.Cells fnm, emon.Port.Cells pa, emon.Port.Cells im, emon.Port.Cells fi, emon.Port.Cells grg, emon.Port.Cells grl, emon.Port.Cells fw, emon.Port.Cells fl, emon.Port.Cells et, emon.Port.Cells pg, emon.Port.Cells sl, emon.Port.Cells cand, int level, emon.Port.Cells fcand, emon.Port.Cells cl, emon.Port.Cells fg, emon.Port.Cells fd, emon.Port.Cells ab, emon.Port.Cells ws) {
        // THE FIGURES (SPEC 10.6): the candidate regions (the image placements, the vector clusters of `emon.asset`, the shaded fills, P7.G's
        // `figure` regions), each measured and judged, the ones that are figures placed among the blocks with their kind, confidence
        // and `labels` (`rs-figures`) into the empty arenas `fnodes fattrs fregions` (the caller swaps them in, then restructures). `cand`
        // is the asset stage's own candidate rows (empty when `assets` is off; `level` is that setting): an image figure learns its row,
        // and at `figures` a region of ours the asset stage did not find is added to it (`as-region-add`). Scratch: `fnm fcand cl fg fd ab ws`.
        // Answers the number of figures.
        int nr = 0;
        int i = 0;
        int row = 0;
        int b = 0;
        int page = 0;
        int x0 = 0;
        int y0 = 0;
        int x1 = 0;
        int y1 = 0;
        int pk = 0;
        int kind = 0;
        int conf = 0;
        int capt = 0;
        int rej = 0;
        int @out = 1;
        int measured = 0;
        int pageh = 0;
        int recur = 0;
        int srcs = 0;
        int link = 0;
        int k = 0;
        emon.Port.CellsDrop(fcand, 0);
        emon.Port.CellsDrop(fd, 0);
        emon.Port.CellsDrop(ws, 0);
        while (i < WsSize) {
            emon.Port.CellsPush(ws, 0);
            i += 1;
        }
        FcImageRows(im, pa, pg, fcand);
        Asset.AsVectorRegions(pa, pg, fcand, cl);
        FcShadingRegions(pa, pages, fcand);
        FcGrgRegions(grg, pages, fcand);
        Asset.AsFigureRows(fcand, pages, nodes, regions, 2, fg);
        FcSignRows(fi, pa, fcand);
        nr = Asset.AsCount(fcand);
        i = 0;
        while (i < (nr * FdStride)) {
            emon.Port.CellsPush(fd, 0);
            i += 1;
        }
        i = 0;
        while (i < nr) {
            emon.Port.CellsSet(fd, (i * FdStride) + 3, -1);
            emon.Port.CellsSet(fd, (i * FdStride) + 4, -1);
            i += 1;
        }
        i = 1;
        while (i < emon.Port.CellsLen(fg)) {
            row = emon.Port.CellsAt(fg, i);
            b = row * CrStride;
            page = emon.Port.CellsAt(fcand, b + CrPage);
            x0 = emon.Port.CellsAt(fcand, b + CrVx);
            y0 = emon.Port.CellsAt(fcand, b + (CrVx + 1));
            x1 = emon.Port.CellsAt(fcand, b + (CrVx + 2));
            y1 = emon.Port.CellsAt(fcand, b + (CrVx + 3));
            pageh = Model.PageH(pages, page - 1);
            recur = FcRecur(fcand, pages, row);
            rej = 1;
            if (measured < FcMaxreg) {
                measured += 1;
                rej = 0;
                if (FcMeasure(pa, grl, fw, fl, et, page, x0, y0, x1, y1, ws) == 0) {
                    rej = FcReject(ws);
                }
            }
            if (FcSignatureOver(sl, page, x0, y0, x1, y1) == 1) {
                rej = 1;
            }
            if (emon.Port.CellsAt(fcand, b + CrKori) == -2) {
                if (FcClaimed(fl, page, x0, y0, x1, y1) == 1) {
                    rej = 1;
                }
            }
            if (emon.Port.CellsAt(fcand, b + CrKori) == -1) {
                pk = FcImageKind(fi, emon.Port.CellsAt(fcand, b + CrRow), x1 - x0, y1 - y0, y0, y1, pageh, recur);
            } else {
                pk = FcVectorKind(ws, x0, y0, x1, y1, pageh, recur);
            }
            kind = pk / 1024;
            conf = pk % 1024;
            capt = FcCaptioned(nodes, regions, fcand, row, page, x0, y0, x1, y1);
            if ((rej == 0) && ((conf >= FcEmit) || (capt == 1))) {
                if (conf < FcEmit) {
                    if (kind == Model.FgUnknown()) {
                        conf = 400;
                    }
                }
                srcs = emon.Port.CellsAt(fcand, b + CrSrc);
                link = -1;
                if (emon.Port.CellsAt(fcand, b + CrKori) == -1) {
                    if (level > 0) {
                        link = FcLink(cand, page, emon.Port.CellsAt(fcand, b + CrBx), emon.Port.CellsAt(fcand, b + (CrBx + 1)), emon.Port.CellsAt(fcand, b + (CrBx + 2)), emon.Port.CellsAt(fcand, b + (CrBx + 3)));
                    }
                }
                if ((level == 2) && (emon.Port.CellsAt(fcand, b + CrOrg) != 0)) {
                    Asset.AsRegionAdd(cand, page, x0, y0, x1, y1);
                }
                k = row * FdStride;
                emon.Port.CellsSet(fd, k, kind);
                emon.Port.CellsSet(fd, k + 1, conf);
                emon.Port.CellsSet(fd, k + 2, srcs);
                emon.Port.CellsSet(fd, k + 3, link);
                emon.Port.CellsSet(fg, @out, row);
                @out += 1;
            }
            i += 1;
        }
        emon.Port.CellsDrop(fg, @out);
        Restruct.RsFigures(nodes, attrs, regions, text, fnodes, fattrs, fregions, fnm, fcand, fg, fd, ab);
        return @out - 1;
    }
}
